csui.define('d2/overrides/nuc/lib/backbone',[
  'nuc/lib/underscore',
  'nuc/lib/backbone'
], function (_, Backbone) {
  'use strict';

  var oldOnModelEvent = Backbone.Collection.prototype._onModelEvent;

  Backbone.Collection.prototype._onModelEvent = function (event, model, collection, options) {
    if (options && options.d2SuppressModelEvents && _.contains(options.d2SuppressModelEvents, event)) {
      return;
    }
    oldOnModelEvent.apply(this, arguments);
  }

  // VE-OCTCR77IV4231514 Fix
  // After the fix done earlier by overriding backbone history navigate to handle space or hebrew text in quick search
  // as well as back navigation from workflow overview to favorites, A regression is seen in workflow overview panel
  // Only workflows of similar type are now listed in the left sidebar
  // Hence reverted the backbone history navigate override and overriding getGash function with conditional check for search use case
  var oldGetHash = Backbone.History.prototype.getHash;

  Backbone.History.prototype.getHash = function () {
    var match = oldGetHash.apply(this, arguments);
    if (match.startsWith('d2/search/where')) {
      return decodeURI(match);
    }
    return match;
  }
});


