csui.define('d2/server.adaptors/models/d2.fetchable.mixin',[
  'nuc/lib/underscore'
], function (_) {
  'use strict';


  var D2FetchableMixin = {
    mixin: function (prototype) {
      var originalFetch = prototype.fetch;

      return _.extend(prototype, {
        makeD2Fetchable: function () {
          return this;
        },
        fetch: function (options) {
          /*Fix for DTWO-79961 -  Promoted action is not displayed in toolbar actions intermittently.
            RCA: In D2SV action are fetched in batches w.r.t. to page size.
            "delayedActions" in a collection is responsible to fetching  the promoted actions.
            As per fetchable.mixin implementation, when a collections fetch is in-progress, then new fetch will be ignored.
            Because of this behavior, when action fetch call is pending in previous page or parent folder, action call will be ignored for next page or navigated child folder.
            Following condition enables the new fetch of object's promoted actions when previous page or parent folder action request is in progress and always fetches the action.
          */
          if (this.fetching === false && this.delayedActions && this.delayedActions.fetching) {
            this.delayedActions.fetching = false;
          }
          return originalFetch.call(this, options);
        }
      });
    }
  };
  return D2FetchableMixin;
});


