            this.sortedColumns = new NodeColumn2Collection();

            var clonedCols = JSON.parse(JSON.stringify(this.clientColumns));
            _.each(clonedCols, function (col) {
              col.sort = false;
            });
            this.sortedColumns.reset(clonedCols);
