    oldRefilter = proto.refilter,
    oldSet = proto.set/*,
    SIGNATURE_LIST_WITH_FIXED_ICON = Object.freeze(['D2-OpenTaskFiles', 'D2-RelationDelete', 'Properties', 'disabled', 'DocPreview'])*/;

