              this.delayedActions.menuType = type === constants.Types.WORKFLOW ? constants.MenuTypes.WORKFLOWS : type === 'bws_item' ? constants.MenuTypes.BWS_ITEMS : (this.options?.d2ActionsOptions?.menuType ?? constants.MenuTypes.CONTEXT);
