csui.define('d2/server.adaptors/models/nodeversions.mixin',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'd2/utils/constants',
  'dctmw/utils/rest.resources',
  'd2/utils/rest.linkrels',
  'd2/utils/server.query.utils',
  'd2/utils/node.version.utils',
  'd2/utils/widget.constants',
  'd2/utils/sort.utils',
  'd2/server.adaptors/converters/servercolumns',
  'i18n!d2/widgets/metadata/panels/versions/impl/nls/lang'
], function (_, $, constants, RestResources, RestLinkrels, serverQueryUtils, nodeVersionUtils, widgetConstants, sortUtils, serverColumnsConverter, lang) {
  'use strict';

  var ServerAdaptorMixin = {

    mixin: function (prototype) {
      var superSyncMethod = prototype.sync,
        superFetchMethod = prototype.fetch;

      return _.extend(prototype, {

        makeServerAdaptor: function (/*options*/) {
          this.columnTypes = {};
          this.widgetType = widgetConstants.D2.VERSIONS;
          this.options = this.options || {};
          return this;
        },

        fetch: function (options) {
          // Check if sort order has changed. If yes, save in coumn preference in server. Do not wait for response
          if (this._lastFilterAndSortCriteria && !_.isEqual(this.orderBy, this._lastFilterAndSortCriteria.orderBy)
            && (this.columnPreference)) {
            this._saveColumnPreference();
          }
          return superFetchMethod.call(this, options);
        },

        url: function () {
          var url = RestLinkrels.getLink(this.node.get('links'), RestLinkrels.VERSION_HISTORY);

          return serverQueryUtils.appendQueryParams(url, {
            scope: this,
            widgetName: this.options.widgetName,
            clientColumns: this.clientColumns,
            sort: !_.isEmpty(this.orderBy),
            parent_id: this.node.get('parent_id')
          });
        },

        /**
         * This method does 3 things:
         *   1. Ensures that column preferences are loaded (if not already done)
         *   2. Fetches the actual versions data
         *   3. Fetches the permission, action and location data for each version and merges the data before calling
         *      original success method
         */
        sync: function (method, collection, options) {
          var me = this,
            w = RestResources.getCurrentUser().get('defaultWidgets'),
            deferred = $.Deferred();
          this.options.widgetName = w[widgetConstants.DEFAULT.VERSIONS] || '';

          // Use newer version of the API
          _.extend(options.headers, {
            'Accept': constants.MediaTypes.DCTM_D2_V1_JSON
          });
          me.fetchColumnPreferences().done(function (isDisableLocationColumn) {
            me.isDisableLocationColumn = isDisableLocationColumn;
            me.fetchVersionModel(method, collection, options, isDisableLocationColumn).done(function () {
              deferred.resolve();
            }).fail(function (err) {
              deferred.reject(err);
            });
          }).fail(function (err) {
            deferred.reject(err);
          });

          return deferred.promise();
        },

        fetchColumnPreferences: function () {
          var me = this,
            deferred = $.Deferred(),
            widgetConfig = serverQueryUtils.getWidgetConfig(widgetConstants.D2.VERSIONS, this.options.widgetName);

          if (this.options.ignoreColumns) {
            return deferred.resolve().promise();
          }

          if (me.clientColumns && me.clientColumns.length !== 0) {
            me.columns.reset(me.clientColumns);
            deferred.resolve();
          } else {
            var isDisableLocationColumn = (widgetConfig && widgetConfig.getParam('is_disable_loc_col_smartview') === "true") || false;
            serverQueryUtils.fetchColumnPreferences({
              scope: me,
              widgetType: widgetConstants.D2.VERSIONS,
              widgetName: me.options.widgetName,
              connector: me.node.connector,
              columnOptions: {
                typeColumn: true,
                reservedColumn: true,
                externalShareColumn: false,
                commentColumn: false,
                favoriteColumn: false,
                locationColumn: {
                  enabled: !isDisableLocationColumn,
                  title: lang.ColumnTitleLocation
                }
              }
            }).done(function (clientCols, columnPreference) {
              me.columnPreference = columnPreference;
              me.clientColumns = clientCols;
              _.each(clientCols, function (col) {
                //Set the initial loading sorting order here from column preference.
                if (col.sort === true && (col.direction)) {
                  me.orderBy = col.column_key + ' ' + col.direction.toLowerCase();
                }
              });
              me.columns.reset(me.clientColumns);
              me.columnTypes = {};
              deferred.resolve(isDisableLocationColumn);
            }).fail(function (err) {
              deferred.reject(err);
            });
          }
          return deferred.promise();
        },

        _saveColumnPreference: function () {
          var me = this,
            sortarr = _.isString(me.orderBy) ? me.orderBy.split(' ') : [];
          if (sortarr.length > 1) {
            //Save column pref.
            serverQueryUtils.saveColumnPreferences({
              scope: me,
              widgetType: widgetConstants.D2.VERSIONS,
              widgetName: me.options.widgetName || '',
              connector: me.node.connector,
              columnPreference: me.columnPreference,
              sortOrder: me.orderBy
            }).done(function (clientCols, columnPreference) {
              me.columnPreference = columnPreference;
              //Do not save clientCols
            });
            //Do nothing on failure.
          }
        },

        fetchVersionModel: function (method, collection, options, isDisableLocationColumn) {
          var me = this,
            deferred = $.Deferred(),
            oldSuccess = options.success,
            oldError = options.error;
          // We don't call parse method, but instead parse manually here itself because we want to append
          // "actions" for the objects before calling original success method
          options.parse = false;
          options.success = function (response, status, xhr) {
            nodeVersionUtils.fetchVersionModelData(response, isDisableLocationColumn, me.node.connector).done(function (response) {
              oldSuccess.call(options.context, response, status, xhr);
              deferred.resolve();
            }).fail(function (error) {
              deferred.reject(error);
            });
          };

          options.error = function (xhr, textStatus, error) {
            oldError.apply(options.context, arguments);
            deferred.reject(xhr, textStatus, error);
          };
          superSyncMethod.call(me, method, collection, options).fail(deferred.reject);
          return deferred.promise();
        },


        compareObjectsForSort: function (property, left, right) {
          var sortSchema = this.columnTypes[property];
          if (!sortSchema) {
            this.columnTypes[property] = {};
            sortSchema = serverColumnsConverter.getSortColumnSchema(this.clientColumns, property);
            this.columnTypes[property] = sortSchema;
          }
          return sortUtils.compare(sortSchema.key, left, right, sortSchema.type, false);
        }

      });
    }

  };

  return ServerAdaptorMixin;
});


csui.define('d2/server.adaptors/models/version.mixin',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'd2/utils/rest.linkrels',
  'dctmw/server.adaptors/converters/node',
  'd2/utils/node.version.utils',
], function ($, _, RestLinkrels, nodeConverter, nodeVersionUtils) {
  'use strict';

  var ServerAdaptorMixin = {
    mixin: function (prototype) {

      var superSyncMethod = prototype.sync;
      prototype.idAttribute = 'id';

      return _.extend(prototype, {
        makeServerAdaptor: function (/*options*/) {
          return this;
        },

        url: function () {
          return RestLinkrels.getLink(this.get('links'), RestLinkrels.SELF);
        },

        sync: function (method, model, options) {
          if (method === 'read') {
            var deferred = $.Deferred();
            var oldSuccess = options.success;
            var oldError = options.error;
            options.parse = false;
            options.success = function (response, status, xhr) {
              var content = {
                'content': response
              };
              var newres = {entries: [content]};
              nodeVersionUtils.fetchVersionModelData(newres, model.collection.isDisableLocationColumn, model.connector).done(function (data) {
                oldSuccess.call(options.context, data[0], status, xhr);
                deferred.resolve();
              }).fail(function (error) {
                deferred.reject(error);
              });
            };

            options.error = function (xhr, textStatus, error) {
              oldError.apply(options.context, arguments);
              deferred.reject(xhr, textStatus, error);
            };
            superSyncMethod.call(this, method, model, options).fail(deferred.reject);
            return deferred.promise();
          } else {
            return superSyncMethod.call(this, method, model, options);
          }

        },

        getParentId: function (args) {
          let parent_id = args?.status?.container?.get('id'),
              isValidParentId = function (id) {
                return id?.indexOf('dql_') !== 0;
              };
          if (!parent_id || !isValidParentId(parent_id)) {
            parent_id = this.get('parent_id_expand')?.id || this.get('parent_id');
          }
          return parent_id;
        },

      });
    }
  };

  return ServerAdaptorMixin;
});


