    var data = response['options_data'] ? response['options_data']['data_1'] : {};
    var obj = [];
    _.each(data, function (value, key) {
      //this was added as part of scenario where if the maxreuslt was exceeded
      // based on dql criteria it returns truncatedResultSetSize instead of limited_results
      if (key !== 'limited_results' && !key.startsWith("truncatedResultSetSize")) {
        obj.push({"value": value.v, "text": value.l || value.v, "category": value.c});
      }
    });
