csui.define('d2/controls/behaviors/wizard.tabable.region.behavior',['module', 'nuc/lib/underscore', 'nuc/lib/jquery',
  'nuc/lib/marionette', 'nuc/utils/log', 'nuc/utils/base',
  'csui/behaviors/keyboard.navigation/tabable.region.behavior',
  'csui/behaviors/keyboard.navigation/tabables.behavior'
], function (module, _, $, Marionette, log, base, TabableRegionBehavior, TabablesBehavior) {
  'use strict';

  var WizardTabableRegionBehavior = TabableRegionBehavior.extend({

      defaults: {
        initialActivationWeight: 1
      },

      constructor: function WizardTabableRegionBehavior(/*options, view*/) {
        TabableRegionBehavior.prototype.constructor.apply(this, arguments);

        // merge behavior defaults into view
        _.extend(this.view, this.defaults);

        _.extend(this.view, {tabableRegionBehavior: this}); // his is set to have access while setting the view as the active region when loaded

        var self = this;
        // add default implementation to view if it does not have one
        _.extend(this.view, {
            // TODO remove use of isTabable because there is no code that gets called when the user
            // presses the tab key
            isTabable: function () {
              return true;  // default: this view can be reached by tab
            },
            currentlyFocusedElement: function (event) {
              var tabElements = this.$(TabablesBehavior.focusablesSelector).filter(':visible:not([disabled])');
              if (tabElements.length) {
                tabElements.prop('tabindex', 0);
              }
              if (!!event && event.shiftKey) {
                return tabElements[tabElements.length - 1];
              } else {
                return tabElements[0];
              }
            },
            onLastTabElement: function (shiftTab, event) {
              var filterCondition = "*[tabindex=0]:visible";
              var visibleElems = this.slidingList && this.slidingList.length > 0 ?
                this.slidingList[this.slidingList.length - 1].find(filterCondition)
                : this.$(filterCondition);
              return (event.target === (shiftTab ? visibleElems[0] : visibleElems[visibleElems.length - 1]));
            },
            fetchFirstFocussableElement: function () {
              return self._currentlyFocusedElementFromView(this, false);
            }
          }
        );

        //This is used to ste the current step as active for any step button actions
        this.listenTo(this.view, 'step:active', function () {
          if (self.view._isRendered) {
            TabablesBehavior.setTabableRegionActive(self);
            TabablesBehavior.setFocusInActiveTabableRegion();
          } else {
            self.listenTo(self.view, 'step:rendered', function () {
              TabablesBehavior.setTabableRegionActive(self);
              TabablesBehavior.setFocusInActiveTabableRegion();
            });
          }
        });
        if (this.view.options && !this.view.options.initialActivationWeight) {
          this.view.options.initialActivationWeight = this.options.initialActivationWeight;
        }
      },
      setInitialTabIndex: function(){
        if(this.view.allForms && this.view.allForms.configuredFocusControlName && !this.view.allFormsRendered) {
          return;
        }else{
          //Refer comment in d2/overrides/csui/behaviors/keyboard.navigation/tabable.region.behavior
          if (!this.currentlyFocusedElement && this.view.isTabable()) {
            let currentlyFocusedElement = this.getCurrentlyFocusedElementFromView();
            currentlyFocusedElement?.off('focus.' + this.view.cid);
          }
          TabableRegionBehavior.prototype.setInitialTabIndex.apply(this);
        }
      },
      getCurrentlyFocusedElementFromView: function (shiftTab) {
        try {
          if (this.view.slidingList && this.view.slidingList.length > 0) {
            return this._currentlyFocusedElementFromView(this.view, shiftTab);
          } else {
            return TabableRegionBehavior.prototype.getCurrentlyFocusedElementFromView.apply(this, arguments);
          }
        } catch (e) {
          console.warn('Could not set as active element: ', this.view.cid, e.message);
        }
      },
      _currentlyFocusedElementFromView: function (view, shiftTab) {
        var filterCondition = ":visible:not([disabled])";
        var tabElements = view.slidingList && view.slidingList.length > 0 ?
          view.slidingList[view.slidingList.length - 1].find(TabablesBehavior.focusablesSelector).filter(filterCondition)
          : view.$(TabablesBehavior.focusablesSelector).filter(filterCondition);
        if (tabElements.length) {
          tabElements.prop('tabindex', 0);
        }
        var focusEl;
        if (shiftTab) {
          focusEl = tabElements[tabElements.length - 1];
        } else {
          focusEl = tabElements[0];
        }
        return (focusEl instanceof $ ? focusEl : $(focusEl));
      }
    }
  );

  return WizardTabableRegionBehavior;
});


csui.define('d2/models/mixins/expressions/expression.executor.mixin',[
  'module', 'nuc/lib/underscore', 'nuc/lib/backbone', 'nuc/utils/log', 'csui/controls/form/pub.sub', 'd2/models/mixins/expressions/expression',
  'dctmw/models/mixins/expressions/expression.executor.mixin',
  'd2/utils/mass.update.utils'
], function (module, _, Backbone, log, PubSub, ExpressionModel, DctmwExpressionExecutorMixin, MassUpdateUtils) {
  'use strict';

  log = log(module.id);

  var ExpressionExecutorMixin = {

    mixin: function (prototype) {

      prototype = DctmwExpressionExecutorMixin.mixin(prototype);

      return _.extend(prototype, {

        getValueForConditionEvaluation: function(sourceView, targetControl ){
          var me = this;

          return function (sourceControlName) {
            var sourceControlPathObj = sourceView._keyPathMap[sourceControlName];
            if (sourceControlPathObj) {
              var sourceViewForm = me.getParentFormForControl(sourceControlName);
              var alpControl = sourceViewForm.getAlpacaControlByPath(sourceControlPathObj.fieldPath);
              var value;
              if (_.isArray(alpControl)) {
                // This is a grid.
                var rowControl = sourceViewForm.shouldApplyRowBasedEvaluation(targetControl, sourceControlName);
                alpControl = rowControl ? [rowControl] : alpControl;
                value = _.pluck(alpControl, 'data');
              } else {
                value = alpControl.getValue();
              }
              value = (_.isArray(alpControl) && alpControl[0].options && alpControl[0].options.massUpdateFileCount)
              || (alpControl.options && alpControl.options.massUpdateFileCount) ? MassUpdateUtils.convertMultipleValues(value) : value;
              return new ExpressionModel(value, alpControl);
            }
          };
        },

        getValueForEvaluateBeforeRender: function(){
          var me = this;
          return function (controlName) {
            var controlPathObj = me._keyPathMap[controlName];
            if (controlPathObj) {
              var formId = controlPathObj.formId;
              var fieldPath = controlPathObj.fieldPath;
              var formModel = me.model.collection.get(formId);
              var val = me.getFieldForPath(formModel.get("data"), "", ".", fieldPath);
              var option = me.getFieldForPath(formModel.get("options"), "fields", ".", fieldPath);
              var type = {options: {_type: option._type}};
              var control = type;
              if (option._repeating === true) {
                control = [];
                _.each(val, function () {
                  control.push(_.clone(type));
                });
              }
              val = option && option.massUpdateFileCount ? MassUpdateUtils.convertMultipleValues(val) : val === null ? "" : val;
              return new ExpressionModel(val, control);
            }
          };
        }
      });
    }
  };
  return ExpressionExecutorMixin;
});


csui.define('d2/models/mixins/expressions/expression.validator.mixin',[
  'module', 'nuc/lib/underscore', 'nuc/lib/backbone', 'nuc/utils/log', 'd2/models/mixins/expressions/expression','dctmw/models/mixins/expressions/expression.validator.mixin', 'd2/utils/mass.update.utils'
], function (module, _, Backbone, log, ExpressionModel, DctmwExpressionValidatorMixin, MassUpdateUtils) {
  'use strict';

  log = log(module.id);

  var ExpressionValidatorMixin = {

    mixin: function (prototype) {

      prototype = DctmwExpressionValidatorMixin.mixin(prototype);

      return _.extend(prototype, {

        getValueForCreateExpressionValidator: function(targetAlpControl){
          var formView = this;
          return function (controlName) {
            var value;
            var control;
            if (targetAlpControl.propertyId === controlName) {
              value = targetAlpControl.getValue();
              control = targetAlpControl;
            } else {
              var controlPathObj = formView._keyPathMap[controlName];
              if (controlPathObj) {
                var sourceForm = formView.getParentFormForControl(controlName);
                var sourceAlpControl = sourceForm.getAlpacaControlByPath(controlPathObj.fieldPath);
                if (_.isArray(sourceAlpControl)) {
                  var rowControl = formView.shouldApplyRowBasedEvaluation(targetAlpControl, controlName);
                  if (rowControl) {
                    control = rowControl;
                    value = rowControl.getValue();
                  } else {
                    control = sourceAlpControl;
                    value = _.pluck(sourceAlpControl, 'data');
                  }
                } else {
                  value = sourceAlpControl.getValue();
                  control = sourceAlpControl;
                }
              }
            }
            value = (_.isArray(control) && control[0].options && control[0].options.massUpdateFileCount)
            || (control.options && control.options.massUpdateFileCount) ? MassUpdateUtils.convertMultipleValues(value) : value;
            return new ExpressionModel(value, control, true);
          };
        },
        getPreExpressionValue: function(control){
          var value = control.getValue();
          value = control.options && control.options.massUpdateFileCount ? MassUpdateUtils.convertMultipleValues(value) : value;
          return value;
        },
      });
    }
  };
  return ExpressionValidatorMixin;
});


