                this.taxonomyChildren = this.taxonomyChildren.length > 0 ?
                    this.taxonomyChildren.reverse() : this.taxonomyChildren;

                this.taxonomyAncestors = this.findTaxonomyAncestors(this, [], true);
                this.taxonomyAncestors = this.taxonomyAncestors.length > 0 ?
                    this.taxonomyAncestors.reverse() : this.taxonomyAncestors;


