csui.define('txt!d2/controls/form/impl/d2tab/tabcontainer.txt',[],function () { return '<div id="{{options.uniqueId}}" class="d2-container d2-set-container d2tabcontainer binf-col-md-12 {{#xif "this.options.tabLevel <= 2"}}d2tabcontainerpadding{{/xif}}" style="display:flex">\n {{#each items}}\n    <div class="d2tabcontaineritemwrapper\n    {{#xif \'this.isControlField ||  this.options.multiCheck\'}}\n    \t{{#xif \'this.options.stretch===true\'}}\n    \t    binf-col-md-12\n    \t{{else}}\n    \t     binf-col-md-6\n    \t{{/xif}}\n        d2-control\n    {{else}}\n        {{#xif "this.options._d2Containertype != null && this.options._d2Containertype === \'d2grid\'"}}\n    \t     csui-form-set-array-wrapper cs-form-set\n        {{else}}\n    \t  {{#xif "this.type === \'array\'"}}\n             cs-form-set\n          {{/xif}}\n       {{/xif}}\n     binf-col-md-12\n     {{/xif}}">\n    {{#item}}{{/item}}\n    </div>\n {{/each}}\n</div>\n';});


