  "nuc/lib/backbone",
  "nuc/lib/marionette",
  'nuc/utils/base',
  'nuc/utils/types/date',
  "csui/models/facets",
  "csui/models/facettopics",
  "csui/behaviors/keyboard.navigation/tabable.region.behavior",
  "d2/controls/facet.bar/facet.bar.items.view",
  'd2/controls/facet.bar/impl/facet.bar.task.date.item.view',
  'dctmw/utils/utils',
  "hbs!d2/controls/facet.bar/impl/facet.bar",
  "i18n!d2/controls/facet.bar/impl/nls/lang",
