csui.define('d2/dialogs/add.version/add.version.utils',['module',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'dctmw/utils/rest.resources',
  'i18n!d2/dialogs/add.version/impl/nls/lang',
], function (module, _, $, Backbone, Marionette, RestResources, lang) {
  "use strict";


  return {

    'UNKNOWN': 'UNKNOWN',

    getFormats: function (filename) {
      var formatList = [];
      if (filename) {
        var ext = filename.split('.').pop().toLowerCase();
        var formats = RestResources.getFormats();
        formatList = formats.where({'dos_extension': ext});
        if (formatList.length) {
          formatList = _.pluck(formatList, 'attributes');
          _.map(formatList, function (item) {
            item.value = item.name;
            item.text = item.description;
            item.s = formatList.length === 1 ? true : item['is-default'];
          });
        } else {
          formatList = [{'value': this.UNKNOWN, 'text': lang.Unknown}];
        }
      }
      return formatList;
    },

    getDefaultFormat: function (formatList) {
      return _.find(formatList, function (format) {
        return format['is-default'] === true;
      });
    },

    isForceThinClientMode: function (options) {
      return ((options.shareInfo && options.shareInfo.useCorePath) || !options.file);
    }

  };

});

csui.define('d2/commands/add.rendition',[
  'require',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'csui/models/command',
  'csui/dialogs/file.open/file.open.dialog',
  'd2/controls/globalmessage/globalmessage',
  'csui/models/fileuploads',
  'dctmw/utils/rest.resources',
  'd2/utils/widget.constants',
  'd2/dialogs/add.version/add.version.utils',
  'i18n!d2/commands/nls/localized.strings',
], function (require, _, $, Backbone, CommandModel, FileOpenDialog, GlobalMessage, UploadFileCollection, RestResources, widgetConstants, AddVersionUtils, lang) {
  'use strict';

  return CommandModel.extend({
    defaults: {
      signature: 'D2-AddRendition',
      command_key: 'D2-AddRendition',
      name: lang.AddToRendition,
      scope: 'single'
    },

    execute: function (status , options = {}) {
      var me = this;
      me.options = options;
      if (me.options?.fileImportUrl) {
        const { docDownloadFileName, exportType } = me.options;
        const { nodes } = status;
        const fieldValues = {
          fileContent: {
            file: docDownloadFileName,
            format: exportType
          },
          nodeModel: nodes,
          signature: me.get("signature")
        };
        me.prepareImportCollection(status);
        me._filterFileFormats();
        me.uploadRendition(status, fieldValues);
      }
      else{
           var fileOpenDialog = new FileOpenDialog({ multiple: false });
           fileOpenDialog.listenTo(fileOpenDialog, 'add:files', function (files) {
           me.files = files;
           me.prepareImportCollection(status);
           fileOpenDialog.destroy();
           me._filterFileFormats();
           me._launchFileSelectorConfirmationDialog(status);
           })
           fileOpenDialog.show();
      }
      return $.Deferred().resolve().promise();
    },

    prepareImportCollection: function (status) {
      var connector = status.context && status.context.getObject('connector');
      var name, mimeType, node;

        if (this.options.suppressDialog) {
          name = this.options.docDownloadFileName;
          mimeType = this.options.exportType;
          node = status.node;
        }
        else if (this.files && this.files.length > 0) {
          name = this.files[0].name;
          mimeType = this.files[0].type;
          node = this.files[0];
        }

        var importModels = {
          name: name,
          mime_type: mimeType,
          state: 'processing',
          count: 1,
          node: node,
          commandContainer: status.container,
          targetLocation: undefined,
          context: status.context
        };
      this.importCollection = new UploadFileCollection([importModels], { connector: connector });
      this.importCollection.map((importModel) => {
       importModel.node = this.options.fileImportUrl ? status.nodes : status.nodes.at(0);
       importModel.unset('node');
     });
    },

    _getFileFormats: function () {
      return this.formatsCollection;
    },

    _filterFileFormats: function () {
      var formats = RestResources.getFormats().where({ is_hidden: false });
      this.formatsCollection = new Backbone.Collection();
      this.formatsCollection.comparator = 'description';
      this.formatsCollection.add(formats);
    },

    _getFileName() {
      var fileName = this.files[0].name;
      var fileBaseName = fileName.substring(0, fileName.lastIndexOf('.'));
      return fileBaseName;
    },

    _getFileExtension() {
      var formats = this._getFileFormats().where({ mime_type: this.files[0].type });
      var fileFormatArr = [];
      for (let i = 0; i < formats.length; i++) {
        fileFormatArr.push({
          "p": i,
          "l": formats[i].get('description'),
          "v": formats[i].get('name')
        });
      }
      return fileFormatArr;
    },

    getDataSourceCallbackForCombo: function () {
      var collectionData = [];
      _.map(this._getFileExtension(), function (data) {
        collectionData.push({
          value: data.v,
          text: data.l,
          s: data.s,
        });
      });
      return collectionData;
    },

        _getFormats: function () {
          return AddVersionUtils.getFormats(this.files[0]?.name);
        },

    _getFormContent() {
      var self = this,
        collectionForm = {
          dialog: {
            content: {
              order: 1,
              "node-picker": {
                id: "file",
                label: lang.AddToRenditionFormLabelNodePicker,
                order: 1,
                isFileOpenDialog: true,
                value: self._getFileName(),
              },
              "combo": {
                id: "file_format",
                label: lang.AddToRenditionFormLabelCombo,
                assistance_type: "custom",
                order: 2,
                o: self._getFormats(),
                dependencyOnControl: 'file',
              },
            },
          },
        };
      return collectionForm;
    },

    _getButtonsList: function () {
      var buttons = {
        showYes: true,
        labelYes: lang.AddItemButtonLabel,
        showNo: false,
        showCancel: true,
      };
      return buttons;
    },

    showProgressPanel: function (status) {
      GlobalMessage.showProgressPanel(this.importCollection, {
        oneFileSuccess: lang.AddToRenditionOneSuccess,
        oneFilePending: lang.AddToRenditionOnePending,
        oneFileFailure: lang.AddToRenditionOneFailure,
        enableCancel: true,
        originatingView: status.originatingView,
        actionType: 'UPLOAD_CONTENT',
        link_command_signature: 'D2-Renditions',
        context: status.context,
        gotoLocationLinkLabel: lang.AddToRenditionLinkLabel,
        configOptions: {
          enhancePanel: this.importCollection.length > 1
        },
        doAutoClose: true,
      });
    },

    _launchFileSelectorConfirmationDialog: function (status) {
      var self = this,
        dfd = $.Deferred(),
        fieldValues = {};
      csui.require([
        "dctmw/dialogs/modal.alert.custom.content/customizable.modal.alert",
        "d2/dialogs/add.rendition/add.rendition.view"
      ], function (ModelAlert, AddRenditionView) {
        var modalView = getModalView(self);

        function getModalView(self) {
          return new AddRenditionView({
            formContent: () => self._getFormContent(),
            collection: status.collection,
            getDataSourceCallbackForCombo: () => self._getFormats(),
            signature: self.get("signature"),
          });
        }

        function onFieldValueUpdate() {
          var modalValue = modalView.getValues();
          if (modalValue.file?.name && (modalValue.file?.name !== self.files[0]?.name)) {
            self.files = [modalValue.file];
          }
          if (_.isUndefined(modalValue.file) || _.isNull(modalValue.file)) {
            self.files = [];
          }
          fieldValues = {};
          fieldValues = {
            fileContent: {
              file: self.files[0],
              format: modalValue.file_format
            },
            nodeModel: status?.nodes?.models[0],
            signature: self.get('signature')
          };
        }

        self.listenTo(modalView, "d2:change:formValidation", onFieldValueUpdate);
        ModelAlert.confirmMessage(
          function (result) {
            if (result === true) {
              self.uploadRendition(status, fieldValues).done(() => {
                dfd.resolve();
              }).fail(() => {
                dfd.reject();
              })
            } else {
              dfd.reject(new Error());
            }
          },
          "",
          lang.AddToRenditionModalHeader,
          {
            buttons: self._getButtonsList(),
            contentView: modalView,
            modalClass: self._getModalClassName(),
          }
        );
      });
      return dfd.promise();
    },
    _getModalClassName() {
      return 'd2-add-to-rendition-model';
    },

    uploadRendition: function (status, fieldValues) {
      var dfd = $.Deferred(),
        self = this, isSameContainer = false;
      this.showProgressPanel(status);
      const fileImportUrl = self.options?.fileImportUrl || '';
      const token = self.options?.bearerToken || '';

      fieldValues.extraFormData = {
        fileImportUrl,
        token
      };
      csui.require(["d2/utils/creation.utils",], function (CreationUtils) {
        var defaultWidgets = RestResources.getCurrentUser().get('defaultWidgets'),
            isRenditionsWidgetEnabled = (defaultWidgets && defaultWidgets[widgetConstants.DEFAULT.RENDITIONS]) ? true : false,
            inRenditionsWidget = status?.context?.viewStateModel?.getViewState('dropdown') === 'renditions' ? true : false;
        CreationUtils._getImportRenditionUrl(fieldValues).done(() => {
          isSameContainer = (isRenditionsWidgetEnabled && !inRenditionsWidget) ? true : undefined;
          self.handleUploadRenditionOperation({ isSuccess: true, targetLocation: isSameContainer });
          const nodeId = self?.options?.fileImportUrl? status?.nodes?.parent?.get('id') : status?.nodes?.models[0]?.get('id');
          if (nodeId) {
            status.originatingView.trigger('d2:add:rendition', nodeId);
          }
          delete self.options;
          dfd.resolve();
        }).fail((error) => {
                  self.handleUploadRenditionOperation({ isSuccess: false });
                  delete self.options;
                  dfd.reject(error);
        });
      });
      return dfd.promise();
    },

    handleUploadRenditionOperation: function (options) {
      this.importCollection.at(0).set({
        state: options.isSuccess ? 'resolved' : 'rejected',
        targetLocation: options.targetLocation
      });
    },
  });
});


