csui.define('d2/dialogs/add.collections/add.to.collection.view',[
  "nuc/lib/jquery",
  "nuc/lib/underscore",
  "nuc/lib/backbone",
  "csui/models/form",
  "d2/controls/behaviors/wizard.tabable.region.behavior",
  "d2/controls/form/d2.form.view",
  "d2/widgets/metadata/utils/form.converter",
  "d2/utils/collection.utils",
  "css!d2/dialogs/add.collections/impl/add.to.collection.view",
], function ($, _, Backbone, FormModel, WizardTabableRegionBehavior, D2FormView, MetadataConverter, CollectionUtils) {
  "use strict";

  var AddToCollectionView = D2FormView.extend({
    className: function () {
      return D2FormView.prototype.className.apply(this, arguments) + " add-to-collection-form";
    },

    constructor: function AddToCollectionView(options) {
      options || (options = {});
      this.node = options.collection;
      var self = this,
        form = MetadataConverter.convertConfig(options.formContent, {
          actionMode: "create",
          layoutMode: "singleCol",
          extendFieldOptions: function (field) {
            field.getDataSourceCallBack = function (attr, alpField) {
              var dfd = $.Deferred(),
                fieldOptions = alpField.options.ds,
                fieldView = alpField.fieldView,
                filter = (fieldOptions && fieldOptions.filter) || "";
              self
                .getCollections(filter, options)
                .done(function (userResponse) {
                  if (userResponse["has-more-records"]) {
                    fieldView.collection.hasMoreRecords = true;
                  } else if (!filter) {
                    fieldView.allUserOptions = (options.sourceCollectionModel)
                                              ?userResponse.options.filter(option => option.value !== options.sourceCollectionModel.get('id'))
                                              :userResponse.options;
                    field.asynchronous = false;
                    delete alpField.options.ds;
                  }
                  self.setCollectionData(userResponse.userData);
                  dfd.resolve(fieldView.allUserOptions || userResponse.options);
                })
                .fail(dfd.reject);
              return dfd.promise();
            };
          },
        });

      options.topAlignedLabel = false;
      options.model = new FormModel(form.propertiesConfig[0]);
      options.model.get("schema")["initial_invalid"] = true;
      options.mode = "create";
      D2FormView.prototype.constructor.apply(this, arguments);

      this.listenTo(this, "valid:field", this._raiseValidChangeEvent);
      this.listenTo(this, "invalid:field", this._raiseInvalidChangeEvent);

    },

    behaviors: {
      TabableRegion: {
        behaviorClass: WizardTabableRegionBehavior,
      },
    },

    setCollectionData: function (usersDump) {
      if (!this.userData) {
        this.userData = {};
      }
      _.extend(this.userData, usersDump);
    },

    getCollections: function (filter, options) {
      return CollectionUtils.getCollections(options.collection.allModels[0], filter, options);
    },
  });
  return AddToCollectionView;
});


