  'csui/behaviors/keyboard.navigation/tabable.region.behavior',
  'd2/controls/behaviors/wizard.tabable.region.behavior',
  'csui/controls/tile/behaviors/perfect.scrolling.behavior',
  'd2/widgets/metadata/utils/form.converter',
  'd2/widgets/metadata/general.panels/d2/d2.general.form.model',
  'd2/controls/form/d2.form.view',
  'dctmw/utils/rest.resources',
  'd2/utils/rest.linkrels',
  'd2/dialogs/create.relation/impl/empty.views/empty.relations.view',
  'd2/dialogs/create.relation/impl/empty.views/empty.child.view',
  'd2/controls/form/fields/d2selectfield.view',
  'd2/dialogs/create.relation/impl/relationItem/child.item.view',
  'i18n!d2/dialogs/create.relation/impl/nls/lang',
  'hbs!d2/dialogs/create.relation/impl/create.relation.form',
