csui.define('d2/models/d2collections/d2.mycollections.model',[
    'nuc/lib/jquery',
    'nuc/models/node/node.model',
    'd2/utils/constants',
    'd2/utils/widget.constants',
    'd2/utils/rest.linkrels',
    'csui/utils/commands',
    'd2/utils/server.query.utils',
    'd2/widgets/d2collections.perspective/impl/d2collections.toolbaritems',
], function( $, NodeModel, constants, widgetConstants, RestLinkrels, commands, serverQueryUtils,  d2collectionsToolbaritems,){
  'use strict';

  var MyCollectionWidgetModel = NodeModel.extend({
      constructor: function MyCollectionWidgetModel(attributes, options) {
          options.d2ActionsOptions = options.d2ActionsOptions || {
              menuType: constants.MenuTypes.COLLECTIONS,
              widgetType: widgetConstants.D2.COLLECTIONS
          };
          options.delayedActionsOptions = options.d2ActionsOptions;
          options.nonPromotedActionsOptions = options.d2ActionsOptions;
          if(!options.toolbarItems ){
            options.toolbarItems= {
                inlineActionbar: d2collectionsToolbaritems.collectionsInlineActionBar
              }
          }
          if(!options?.collection?.expanded && options.toolbarItems){
            options.nonPromotedActionCommands = commands.getSignatures(options.toolbarItems);
            options.promotedActionCommands = [];
          }
          this.options = options;
          NodeModel.prototype.constructor.apply(this, arguments);

          this.set("type", constants.Types.COLLECTIONS);
      },

      url: function(){
        return RestLinkrels.getLink(this.get("links"), RestLinkrels.SELF);
      },
      sync: function (method/* model, options*/) {
        if(method === 'delete') {
            return NodeModel.prototype.sync.apply(this, arguments);
        }
        var me = this,
            dfd = $.Deferred(),
            id = this.get("id"),
            params = {
                actions: {
                    menuType: constants.MenuTypes.COLLECTIONS,
                    widgetType: widgetConstants.D2.COLLECTIONS
                },
                ids: [id],
                connector: me.connector
            };
        serverQueryUtils.fetchDataForObjects(params).done(function (output) {
            me.set("actions",(output.actions && output.actions[id]) || []);
            dfd.resolve();
        }).fail(function () {
            dfd.reject.apply(dfd, arguments);
        });

        return dfd.promise();
     },
      parse: function(response) {
        return response.entries ? response.entries[0].properties : response;
      },

  });

  return MyCollectionWidgetModel;
});

csui.define('d2/models/d2collections/d2collections.items.model',[
    'nuc/lib/underscore',
    'nuc/lib/jquery',
    'csui/utils/commands',
    'nuc/models/node/node.model',
    'd2/utils/constants',
    'd2/utils/widget.constants',
    'd2/utils/rest.linkrels'
], function(_, $, commands, NodeModel, constants, widgetConstants, RestLinkrels){
    'use strict';

    var CollectionItemWidgetModel = NodeModel.extend({
        constructor: function CollectionItemWidgetModel(attributes, options) {
            options = options || {};

            options.d2ActionsOptions = options.d2ActionsOptions || {
                menuType: constants.MenuTypes.COLLECTION_ITEMS,
                widgetType: widgetConstants.D2.COLLECTIONS
            };

            options.delayedActionsOptions = options.d2ActionsOptions;
            options.nonPromotedActionsOptions = options.d2ActionsOptions;

            if(!options?.collection?.expanded && options?.collection?.options.toolbarItems){
                options.nonPromotedActionCommands = commands.getSignatures(options?.collection?.options.toolbarItems);
                options.promotedActionCommands = [];
            }

            this.options = options;

            NodeModel.prototype.constructor.apply(this, arguments);
        },

        sync: function (method, model, options) {
            if(method === 'delete') {
                let oldSuccess = options.success,
                    oldError = options.error,
                    dfd = $.Deferred();

                options.success = function (model, status, xhr) {
                    oldSuccess.call(options.context, model, status, xhr);
                    dfd.resolve();
                };
                options.error = function (xhr, statusText, error) {
                    oldError.call(options.context, xhr, statusText, error);
                    dfd.reject({responseJSON: {error: error.message}});
                };
                this.deleteModel(model, options);
                return dfd.promise();
            }
            return NodeModel.prototype.sync.apply(this, arguments);
        },

        deleteModel: function(model, options) {
            let me = this,
                data = {"items_chronicle_id": [model.get("i_chronicle_id")]};
            _.extend(options, {
                contentType: constants.MediaTypes.DCTM_JSON,
                type: 'DELETE',
                url: me._getCollectionItemUrl('parent'),
                data: JSON.stringify(data)
            });
            $.ajax(this.connector.extendAjaxOptions(options));
        },

        _getCollectionItemUrl: function(from) {
            from = from ? 'parentLinks': 'links';
            let containerUrl= RestLinkrels.getLink(this.get(from), RestLinkrels.SELF),
                url = containerUrl?.indexOf("?") > -1 ? containerUrl?.slice(0,containerUrl.indexOf("?")) : containerUrl;
            return url;
        }
   });
    return CollectionItemWidgetModel;
});

csui.define('d2/models/d2collections/table/d2collections.column.collection',[
  'nuc/lib/underscore',
  'nuc/lib/backbone',
], function (_, Backbone) {
  'use strict';

  var D2CollectionColumnModel = Backbone.Model.extend({

    idAttribute: "key",

    defaults: {
      key: null,  // key from the resource definitions
      sequence: 0 // smaller number moves the column to the front
    }

  });

  var D2CollectionWidgetColumnCollection = Backbone.Collection.extend({

    model: D2CollectionColumnModel,
    comparator: "sequence",

    getColumnKeys: function () {
      return this.pluck('key');
    },

    deepClone: function () {
      return new D2CollectionWidgetColumnCollection(
        this.map(function (column) {
          return column.attributes;
        }));
    }
  });

  return D2CollectionWidgetColumnCollection;
});

csui.define('d2/models/d2collections/table/d2collections.items.client.columns',[
    'nuc/lib/underscore',
    'nuc/lib/backbone',
    'i18n!csui/models/widget/nls/lang'
], function(_, Backbone, lang){
    'use strict';

    var D2CollectionItemColumnModel = Backbone.Model.extend({
        idAttribute: null,

        constructor: function D2CollectionItemColumnModel(attributes, options) {
            if (attributes && !attributes.title) {
                attributes.title = lang[attributes.column_key];
            }
            D2CollectionItemColumnModel.__super__.constructor.call(this, attributes, options);
        }
    });

    var D2CollectionItemWidgetColumnCollection = Backbone.Collection.extend({
        model: D2CollectionItemColumnModel,

        resetCollection: function (response, options) {
            var columns, me = this;
            if (response && response.columns) {
                // columns from server
                columns = _.map(response.columns, function (column) {
                    return new me.model(column);
                });
            }
            this.reset(columns, options);
            this.fetched = true;
        }
    });

    return D2CollectionItemWidgetColumnCollection;
});


