    loadMobileSupportedMenuItems: function (toolbars, masterActionsList) {
      function addToToolbar(command, toolbar) {
        _.each(['inlineToolbar', 'multiSelectToolbar', 'containerToolbar'], function (toolbarType) {
          toolbar[toolbarType] && toolbar[toolbarType].addItem(command);
        });
      }

      var mobileSupportedMenuTypes = [constants.MenuTypes.SUBMENU_DOCUMENT_D2_LIFECYCLE_ATTACH,
        constants.MenuTypes.SUBMENU_DOCUMENT_LIFECYCLE,
        constants.MenuTypes.SUBMENU_LAUNCH_WORKFLOW];

      var actionList = _.deepClone(masterActionsList),
        filteredItems = _.filter(actionList, function (actionItem) {
          var menuType = (actionItem.actionProperties || {}).menuType,
            subMenuType = (actionItem.actionProperties || {}).subMenuType,
            doAttach = false;
          if ((menuType && _.contains(mobileSupportedMenuTypes, menuType)) ||
            (subMenuType && _.contains(mobileSupportedMenuTypes, subMenuType))) {
            doAttach = true;
          } else if (actionItem.signature === 'D2-LifeCycleStateChange' || actionItem.signature === 'D2-LaunchWorkflow'
            || actionItem.signature === 'placeholder') {
            doAttach = true;
          }
          if (doAttach) {
            var iconName = actionItem.iconName || '';
            actionItem.icon = 'icon ' + iconName;
            actionItem.menuIcon = 'icon ' + iconName;
          }
          return doAttach;
        });

      var groupedActions = new ToolItemsFactory(getGroupedActions('other', filteredItems));
      _.each(toolbars, function (toolbar) {
        groupedActions.collection.each(function (lifecycleCommand) {
          addToToolbar(lifecycleCommand, toolbar);
        });
      });
    },

