csui.define('d2/utils/perspectives/app.scope.collection',[
  'nuc/lib/underscore',
  'd2/utils/landingpage/default.widget.types.map',
  'd2/utils/widget.constants',
  'dctmw/utils/rule.matcher.collection'
], function (_, defaultWidgetTypesMap, widgetConstants, RuleMatcherCollection) {
  'use strict';

  var RuleMatcherModel = RuleMatcherCollection.prototype.model;
  var D2ApplicationScopeModel = RuleMatcherModel.extend({
    defaults: {
      _srcNS: 'd2',
      perspectiveJson: '',
      sequence: 1000,
      validateConfig: function(/*widgetConfig*/) {
        return {status: true};
      },
      beforeActivateScope: function() {},
      afterDeactivateScope: function() {}
    },

    constructor: function D2ApplicationScopeModel(/*attributes, options*/) {
      RuleMatcherModel.apply(this, arguments);
    },

    validateConfig: function() {
      var validator = this.get('validateConfig'),
        validationResult = {status: true};

      try {
        if(_.isFunction(validator)) {
          _.extend(validationResult, validator.apply(this, arguments));
        }
      } catch(e) {
        console.error(e);
        validationResult = {status: false, errorMessage: e.message};
      }

      return validationResult;
    },

    getPerspectiveJson: function() {
      var perspectiveJson = this.get('perspectiveJson') || this.get('applicationScope') || 'Unknown';
      if(!perspectiveJson.endsWith('.json')) {
        perspectiveJson += '.json';
      }
      if(perspectiveJson.indexOf("/") === -1) {
        perspectiveJson = this.get('_srcNS') + "/utils/perspectives/" + perspectiveJson;
      }
      this.set('perspectiveJson', perspectiveJson, {silent: true});
      return perspectiveJson;
    },

    getTitle: function() {
      return this.get('defaultTitle');
    },

    getDefaultWidgetType: function() {
      return this.get('defaultWidgetType');
    },

    getWidgetType: function() {
      if(!this.get('widgetType') && this.getDefaultWidgetType()) {
        this.set('widgetType', defaultWidgetTypesMap.getMaps()[this.getDefaultWidgetType()].type, {silent: true});
      }
      return this.get('widgetType');
    },

    applyBeforeActivateHook: function() {
      var fnBeforeActivate = this.get('beforeActivateScope') || _.noop,
        isActive = this.get('isActive'),
        retVal;

      if(!isActive) {
        this.set('isActive', true);
        if(_.isFunction(fnBeforeActivate)) {
          try {
            retVal = fnBeforeActivate;
          }catch(e){
            console.warn(e);
          }
        }
      }

      return retVal;
    },

    applyAfterDeactivateHook: function() {
      var fnAfterDeactivate = this.get('afterDeactivateScope') || _.noop,
        isActive = this.get('isActive');

      if(isActive) {
        this.set('isActive', false);
        if(_.isFunction(fnAfterDeactivate)) {
          try {
            fnAfterDeactivate();
          }catch(e) {
            console.warn(e);
          }
        }
      }
    }
  });

  var D2ApplicationScopeCollection = RuleMatcherCollection.extend({
    model: D2ApplicationScopeModel,
    comparator: 'sequence',

    getModelForScope: function(applicationScope) {
      return _
        .chain(this.findAllByRule({equals: {applicationScope: applicationScope}}))
        .groupBy(function(m){return m.get('applicationScope');})
        .map(_.first)
        .first()
        .value();
    },

    getActiveApplicationScopeModels: function() {
      return _
        .chain(this.findAllByRule({not: {equals: {applicationScope: ''}}}))
        .groupBy(function(m){return m.get('applicationScope');})
        .map(_.first)
        .value();
    },

    getActiveApplicationScopes: function() {
      return _
        .chain(this.getActiveApplicationScopeModels())
        .map(function(m){return m.get('applicationScope');})
        .compact()
        .value();
    }
  });

  return D2ApplicationScopeCollection;
});




csui.define('d2/utils/perspectives/app.scope.perspectives',[
  'nuc/lib/underscore',
  'd2/utils/perspectives/app.scope.collection',
  'csui-ext!d2/utils/perspectives/app.scope.perspectives'
], function (_, D2ApplicationScopeCollection, extAppScopes) {
  'use strict';

  var appScopePerspectives = new D2ApplicationScopeCollection();

  var appScopes = [];

  if (extAppScopes) {
    appScopes = appScopes.concat(_.flatten(extAppScopes, true));
  }

  appScopePerspectives.add(appScopes);

  return appScopePerspectives;
});


csui.define('d2/utils/workerInstance',[], function () {
    'use strict'
    return {
        workerFunction: function () {

            // Listen for messages from the main thread
            self.addEventListener(
                'message',
                async (e) => {

                    var { url, options } = e.data;
                    try {
                        options.credentials = 'include';
                        const response = await fetch(url, options);
                        const data = await response.json();
                        if (response.status === 401) {
                            self.postMessage({ status: 'unauthorized' });
                        } else if(response.status >= 400){
                            self.postMessage({status: 'error', response: response.message});
                        } else {
                            self.postMessage({ status: 'success', data });
                        }
                    } catch (error) {
                        if (error.status === 401) {
                            self.postMessage({ status: 'unauthorized' });
                        } else {
                            self.postMessage({ status: 'error', error: error.message });
                        }
                    }
                },
                false
            );
        },
    };
});


